corrected_code:
app.get('/api/orders/:id', async (req, res) => {
  const order = await Order.findByPk(req.params.id);
  if (!order) return res.status(404).send('Not Found');
  if (order.userId !== req.user.id) return res.status(403).send('Forbidden');
  res.json(order);
});
